assets.styles.css:
/* Washi: sumi ink on handmade paper, one vermilion seal. Quiet rules, generous margins, no boxes where a line will do. */

/* Paper fibres and a faint manuscript grid behind the app and every scene. */
[data-part="shell.canvas"], .scs .bgm {
  background-color: var(--bk-surface-base) !important;
  background-image:
    radial-gradient(ellipse 60% 40% at 18% 12%, color-mix(in srgb, var(--bk-surface-field) 70%, transparent), transparent 70%),
    radial-gradient(ellipse 50% 50% at 86% 78%, color-mix(in srgb, var(--bk-surface-well) 80%, transparent), transparent 70%),
    linear-gradient(color-mix(in srgb, var(--bk-line-track) 28%, transparent) 1px, transparent 1px),
    linear-gradient(90deg, color-mix(in srgb, var(--bk-line-track) 28%, transparent) 1px, transparent 1px) !important;
  background-size: auto, auto, 32px 32px, 32px 32px !important;
}

/* The display face for every big title, set light and wide like a brush-written heading. */
[data-part="shell.title"] h1, [data-part="settings.page-head"] h1, [data-part="scenes.header"] h1,
[data-part="library.section.header"] h2, [data-part="ui.section-header"] h2 {
  font-family: var(--font-fancy); font-weight: 500; letter-spacing: -0.01em;
}

/* The seal: a small vermilion hanko beside the scene name and the title. */
.scs .sh .nm::before, [data-part="shell.title"] h1::after {
  content: ""; display: inline-block; width: .9em; height: .9em; margin-right: .55em; vertical-align: -0.1em;
  background: var(--bk-role-brand-text);
  box-shadow: inset 0 0 0 2px var(--bk-role-brand-text), inset 0 0 0 3.5px var(--bk-surface-panel);
  transform: rotate(-4deg);
}
[data-part="shell.title"] h1::after { width: .32em; height: .32em; margin: 0 0 0 .18em; vertical-align: .9em; }

/* Scene header: one ink rule instead of a bar. */
.scs .sh { background: color-mix(in srgb, var(--bk-surface-base) 88%, transparent); border-bottom: 1px solid var(--bk-line-strong); }
.scs .sh .nm { letter-spacing: .22em; }

/* Tools read as a row of quiet index words, underlined in vermilion when open. */
[data-part="scene.wings"] button[data-control] {
  border-color: transparent !important; background: transparent !important; box-shadow: none !important;
  border-bottom: 2px solid transparent !important;
}
[data-part="scene.wings"] button[data-control]:hover { border-bottom-color: var(--bk-line) !important; }
[data-part="scene.wings"] button[data-control][aria-pressed="true"], [data-part="scene.wings"] button[data-control][aria-expanded="true"] {
  border-bottom-color: var(--bk-role-brand-text) !important; color: var(--bk-text);
}

/* Portraits sit in a paper mount, the way a print is framed. */
.scs .msg .por {
  border: 1px solid var(--bk-line-strong) !important;
  box-shadow: inset 0 0 0 5px var(--bk-surface-panel), inset 0 0 0 6px var(--bk-line) !important;
}

/* A character's lines carry a thin vermilion margin rule; the speaker is set in spaced small capitals. */
.scs > .play .msg.char .body { border-left: 1px solid color-mix(in srgb, var(--bk-role-brand-text) 45%, transparent); padding-left: 18px !important; }
.scs .msg .spk { letter-spacing: .24em !important; font-size: .78em !important; }
.scs .msg .prose { line-height: 1.85; }
.scs .msg .prose q, .scs .msg .prose .q { color: var(--bk-role-brand-text); }

/* The composer is a single ink line on paper. */
.scs .dockbar { background: linear-gradient(transparent, color-mix(in srgb, var(--bk-surface-base) 92%, transparent) 40%) !important; }
.scs .dockbar .cap {
  background: var(--bk-surface-field) !important;
  box-shadow: 0 10px 30px -22px color-mix(in srgb, var(--bk-text) 70%, transparent);
}

/* Library covers get the same mount as portraits. */
[data-part="library.card"] { box-shadow: 0 0 0 5px var(--bk-surface-panel), 0 0 0 6px var(--bk-line), 0 16px 28px -22px color-mix(in srgb, var(--bk-text) 55%, transparent); }

/* The dock is a strip of paper held by one rule. */
[data-part="shell.nav"] nav { background: var(--bk-surface-panel) !important; border: 0 !important; border-top: 1px solid var(--bk-line-strong) !important; box-shadow: 0 -12px 30px -26px color-mix(in srgb, var(--bk-text) 60%, transparent) !important; }
[data-part="shell.nav.tile"][aria-current="page"] { background: transparent !important; color: var(--bk-role-brand-text) !important; box-shadow: inset 0 -2px 0 var(--bk-role-brand-text) !important; }
